#!/usr/bin/env node
/**
 * Extended AI Summaries Batch Processor
 * 
 * This script extracts text from PDFs and outputs document data for AI processing.
 * The AI summaries will be generated by calling the Task tool for each document.
 * 
 * Usage: 
 * 1. Run: node scripts/process-summaries.mjs extract
 *    This outputs a JSON array of documents with extracted text
 * 
 * 2. Process each document with AI and save results
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { getDocument } from 'pdfjs-dist/legacy/build/pdf.mjs';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const ROOT_DIR = path.resolve(__dirname, '..');
const PUBLIC_DIR = path.join(ROOT_DIR, 'public');
const LIBRARY_DIR = path.join(PUBLIC_DIR, 'library');
const SUMMARIES_DIR = path.join(LIBRARY_DIR, 'summaries');
const STATE_FILE = path.join(ROOT_DIR, 'scripts', '.summary-progress.json');

// Documents to skip
const SKIP_IDS = [
  'form-notification-roadworks', 'form-variation-standards', 'form-swms-template',
  'form-incident-report', 'form-daily-diary', 'form-risk-assessment', 'form-induction-checklist',
  'mrwa-spec-202'
];

// External only documents
const EXTERNAL_ONLY_IDS = [
  'whs-construction-cop', 'whs-workplace-traffic', 'whs-swms-guide',
  'whs-records-guide', 'as-1742-3', 'as-nzs-31000', 'agrs-part-3-safe-speed'
];

// Large documents with split pages
const LARGE_DOCUMENTS = {
  'mrwa-tmp-wheatbelt-0922-part1': { pagesDir: path.join(LIBRARY_DIR, 'mrwa', 'tmp', 'pages'), maxPages: 10 },
  'mrwa-tmp-wheatbelt-0922-part2': { pagesDir: path.join(LIBRARY_DIR, 'mrwa', 'tmp', 'pages'), maxPages: 10 },
  'agttm-part-9': { pagesDir: path.join(LIBRARY_DIR, 'standards', 'agttm', 'part-9', 'pages'), maxPages: 10 }
};

function loadState() {
  if (fs.existsSync(STATE_FILE)) return JSON.parse(fs.readFileSync(STATE_FILE, 'utf-8'));
  return { started: new Date().toISOString(), completed: [], failed: [], currentDocument: null };
}

function saveState(state) {
  state.lastUpdated = new Date().toISOString();
  fs.writeFileSync(STATE_FILE, JSON.stringify(state, null, 2));
}

function loadRegistry() {
  return JSON.parse(fs.readFileSync(path.join(LIBRARY_DIR, 'registry.json'), 'utf-8'));
}

function findPdfPath(doc) {
  if (!doc.file) return null;
  const publicPath = path.join(PUBLIC_DIR, doc.file);
  if (fs.existsSync(publicPath)) {
    const buffer = fs.readFileSync(publicPath);
    if (buffer.slice(0, 5).toString() === '%PDF-') return publicPath;
  }
  return null;
}

function getSplitPages(config) {
  if (!config.pagesDir || !fs.existsSync(config.pagesDir)) return [];
  return fs.readdirSync(config.pagesDir)
    .filter(f => f.endsWith('.pdf') && /^page-\d+\.pdf$/.test(f))
    .sort((a, b) => parseInt(a.match(/\d+/)[0]) - parseInt(b.match(/\d+/)[0]))
    .slice(0, config.maxPages)
    .map(f => path.join(config.pagesDir, f));
}

async function extractPdfText(pdfPath, maxPages = 20) {
  try {
    const buffer = fs.readFileSync(pdfPath);
    const loadingTask = getDocument({ data: new Uint8Array(buffer), useSystemFonts: true });
    const pdf = await loadingTask.promise;
    let text = '';
    for (let i = 1; i <= Math.min(pdf.numPages, maxPages); i++) {
      const page = await pdf.getPage(i);
      const content = await page.getTextContent();
      text += content.items.map(item => item.str).join(' ') + '\n';
    }
    return text;
  } catch (error) {
    console.error(`Error extracting from ${pdfPath}: ${error.message}`);
    return '';
  }
}

async function main() {
  const command = process.argv[2] || 'list';
  const state = loadState();
  const registry = loadRegistry();

  if (command === 'list') {
    // List documents to process
    const toProcess = [];
    for (const doc of registry.documents) {
      if (SKIP_IDS.includes(doc.id)) continue;
      if (EXTERNAL_ONLY_IDS.includes(doc.id)) continue;
      if (state.completed.includes(doc.id)) continue;
      toProcess.push({ id: doc.id, title: doc.title, type: doc.type, agency: doc.agency });
    }
    console.log(JSON.stringify(toProcess, null, 2));
    return;
  }

  if (command === 'extract') {
    const docId = process.argv[3];
    const doc = registry.documents.find(d => d.id === docId);
    if (!doc) { console.error('Document not found'); return; }

    let text = '';
    if (LARGE_DOCUMENTS[docId]) {
      const pages = getSplitPages(LARGE_DOCUMENTS[docId]);
      for (const page of pages) {
        text += await extractPdfText(page, 5) + '\n';
        if (text.length > 15000) break;
      }
    } else {
      const pdfPath = findPdfPath(doc);
      if (pdfPath) text = await extractPdfText(pdfPath);
    }

    console.log(JSON.stringify({
      id: doc.id,
      title: doc.title,
      type: doc.type,
      agency: doc.agency,
      text: text.substring(0, 15000),
      textLength: text.length
    }));
    return;
  }

  if (command === 'save') {
    const docId = process.argv[3];
    const summaryJson = process.argv[4];
    
    const existingPath = path.join(SUMMARIES_DIR, `${docId}.json`);
    const existing = fs.existsSync(existingPath) ? JSON.parse(fs.readFileSync(existingPath, 'utf-8')) : {};
    
    const aiSummary = JSON.parse(summaryJson);
    const merged = {
      ...existing,
      title: aiSummary.title || existing.title,
      abstract: aiSummary.abstract || existing.abstract || '',
      keywords: aiSummary.keywords || existing.keywords || [],
      targetAudience: aiSummary.targetAudience || [],
      completeSections: existing.completeSections || [],
      keyRequirements: aiSummary.keyRequirements || [],
      complianceNotes: aiSummary.complianceNotes || [],
      crossReferences: aiSummary.crossReferences || [],
      lastProcessed: new Date().toISOString()
    };
    
    fs.writeFileSync(existingPath, JSON.stringify(merged, null, 2));
    state.completed.push(docId);
    saveState(state);
    console.log(`✅ Saved summary for ${docId}`);
    return;
  }

  if (command === 'status') {
    console.log(JSON.stringify({
      total: registry.documents.length,
      completed: state.completed.length,
      remaining: registry.documents.length - state.completed.length - SKIP_IDS.length - EXTERNAL_ONLY_IDS.length,
      completedIds: state.completed
    }, null, 2));
    return;
  }
}

main().catch(console.error);
